/**
 * Benchmark: `pnpm --filter @bax-print/nest bench`. Prints a table and writes
 * bench/RESULTS.md (generated; do not edit by hand).
 */
import { writeFileSync } from "node:fs";
import { perfectInstances, PERFECT_SEEDS, PERFECT_SIZES, shopMix, type BenchInstance } from "./generate.js";
import { loadThresholds, runInstance, summarize, type Recipe, type Summary } from "./measure.js";

const RECIPES: readonly Recipe[] = [
  { algorithm: "maxrects", heuristic: "bssf" },
  { algorithm: "maxrects", heuristic: "blsf" },
  { algorithm: "maxrects", heuristic: "baf" },
  { algorithm: "maxrects", heuristic: "bl" },
  { algorithm: "skyline", heuristic: "bl" },
  { algorithm: "skyline", heuristic: "mwf" },
  { algorithm: "auto" },
];

interface Row {
  readonly set: string;
  readonly recipe: Recipe;
  readonly n: number;
  readonly summary: Summary;
}

const HEADER = ["set", "algorithm", "heuristic", "n", "runs", "mean util", "worst util", "length/opt", "mean ms"];

function percent(value: number): string {
  return `${(value * 100).toFixed(1)}%`;
}

function cells(row: Row): string[] {
  const { summary } = row;
  return [
    row.set,
    row.recipe.algorithm,
    row.recipe.heuristic ?? "-",
    String(row.n),
    String(summary.runs),
    percent(summary.meanUtilization),
    percent(summary.worstUtilization),
    summary.meanLengthRatio === undefined ? "-" : summary.meanLengthRatio.toFixed(3),
    summary.meanMs.toFixed(1),
  ];
}

function textTable(rows: readonly string[][]): string {
  const widths = HEADER.map((_, i) => Math.max(...[HEADER, ...rows].map((r) => (r[i] ?? "").length)));
  const line = (r: readonly string[]): string => r.map((c, i) => c.padEnd(widths[i] ?? 0)).join("  ");
  return [line(HEADER), line(widths.map((w) => "-".repeat(w))), ...rows.map(line)].join("\n");
}

function markdownTable(rows: readonly string[][]): string {
  const line = (r: readonly string[]): string => `| ${r.join(" | ")} |`;
  return [line(HEADER), line(HEADER.map(() => "---")), ...rows.map(line)].join("\n");
}

function main(): void {
  const { timeBudgetMs } = loadThresholds();
  const sets: { name: string; n: number; instances: BenchInstance[] }[] = [
    ...PERFECT_SIZES.map((n) => ({ name: "perfect", n, instances: perfectInstances([n]) })),
    { name: "shop", n: 40, instances: Array.from({ length: PERFECT_SEEDS }, (_, i) => shopMix(i + 1)) },
  ];
  const rows: Row[] = [];
  for (const set of sets) {
    for (const recipe of RECIPES) {
      const results = set.instances.map((instance) => runInstance(instance, recipe, timeBudgetMs));
      const row = { set: set.name, recipe, n: set.n, summary: summarize(results) };
      rows.push(row);
      process.stdout.write(`${cells(row).join("  ")}\n`);
    }
  }
  const table = rows.map(cells);
  process.stdout.write(`\n${textTable(table)}\n`);

  const markdown = [
    "# Nesting benchmark results",
    "",
    "Generated by `bench/run.ts`; do not edit by hand. Timings depend on the machine.",
    "",
    `- perfect: guillotine-cut ${"1000 × 1000"} pt strips (optimum known), ${PERFECT_SEEDS} seeds per n, rotation any, gutter 0.`,
    `- shop: 40 copies of common print sizes on a 1626 mm roll, ${PERFECT_SEEDS} seeds, rotation any, gutter 0.`,
    `- auto runs with a ${timeBudgetMs} ms budget.`,
    "",
    markdownTable(table),
    "",
  ].join("\n");
  writeFileSync(new URL("./RESULTS.md", import.meta.url), markdown);
}

main();
